let language='en';
let storedMotion;
try {language=localStorage.getItem('portfolio-language')==='ar'?'ar':'en';storedMotion=localStorage.getItem('portfolio-motion');}catch{}
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
let motionPaused=storedMotion ? storedMotion==='paused' : reducedMotion.matches;
const dialog=document.querySelector('#project-dialog');
let activeProject=null;
const t=key=>translations[language][key];
const localized=values=>values[language==='ar'?1:0];
function renderProjects(){
 document.querySelector('#projects').innerHTML=projects.map((p,i)=>`<article class="project-card reveal"><button class="project-open" data-project="${i}" aria-label="${language==='ar'?'عرض تفاصيل':'View details for'} ${p.name}" aria-haspopup="dialog"><div class="project-art" style="--project-bg:${p.bg};--project-fg:${p.fg}"><div class="art-grid" aria-hidden="true"></div><div class="art-top"><span>${String(i+1).padStart(2,'0')} / ${t(p.desktop?'desktop':'mobile')}</span>${p.wip?`<span class="wip">${t('inDevelopment')}</span>`:'<span aria-hidden="true">↗</span>'}</div><div class="art-name" dir="ltr">${p.name}<span style="font-weight:400;opacity:.5">.</span></div><div class="art-bottom"><span>${localized(p.category)}</span><span class="art-mark" aria-hidden="true">${p.mark}</span></div></div><div class="project-info"><div><h3 dir="ltr">${p.name}</h3><p>${localized(p.subtitle)}</p></div><span class="project-arrow" aria-hidden="true">↗</span></div></button><div class="project-tags">${p.tags.map(tag=>`<span>${tag}</span>`).join('')}</div></article>`).join('');
 observeReveals();
}
function renderDialog(index){
 const p=projects[index];
 document.querySelector('#dialog-content').innerHTML=`<div class="dialog-eyebrow">${t('projectDetails')}${p.wip?' · '+t('inDevelopment'):''}</div><h2 id="dialog-title" dir="ltr">${p.name}</h2><p>${localized(p.description)}</p><div class="project-tags">${p.tags.map(tag=>`<span>${tag}</span>`).join('')}</div>${p.wip?`<p class="dialog-note">${t('medcareNote')}</p>`:''}<a class="button primary" href="https://wa.me/201098103777?text=${encodeURIComponent(language==='ar'?'أهلًا يا بشمهندس أحمد، حابب أتكلم معاك عن مشروع مشابه لـ '+p.name:'Hi Eng. Ahmed, I would like to discuss a project similar to '+p.name)}" target="_blank" rel="noopener noreferrer"><span>${t('projectCta')}</span><span>↗</span></a>`;
 dialog.setAttribute('aria-labelledby','dialog-title');
}
function setLanguage(lang){
 language=lang;document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';
 document.querySelectorAll('[data-i18n]').forEach(el=>{el.innerHTML=t(el.dataset.i18n)});
 const button=document.querySelector('#language');button.innerHTML=lang==='en'?'عربي <span aria-hidden="true">◎</span>':'English <span aria-hidden="true">◎</span>';button.setAttribute('aria-label',lang==='en'?'Switch to Arabic':'التبديل إلى الإنجليزية');
 document.querySelector('nav').setAttribute('aria-label',lang==='en'?'Main navigation':'التنقل الرئيسي');
 document.querySelector('.dialog-close').setAttribute('aria-label',t('projectClose'));
 document.title=lang==='en'?'Eng. Ahmed Alnagdy — Mobile App Developer':'م. أحمد النجدي — مطوّر تطبيقات موبايل';
 document.querySelector('meta[name="description"]').content=lang==='en'?'Eng. Ahmed Alnagdy — mobile application developer with 5 years of experience. Flutter, iOS, Android, and desktop applications.':'م. أحمد النجدي — مطوّر تطبيقات بخبرة ٥ سنوات. تطبيقات Flutter وiOS وأندرويد وسطح المكتب.';
 renderProjects();updateMotion();if(activeProject!==null)renderDialog(activeProject);
 try{localStorage.setItem('portfolio-language',lang)}catch{}
}
let observer;
function observeReveals(){
 if(!('IntersectionObserver' in window))return;
 if(!observer)observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.07});
 document.querySelectorAll('.reveal:not(.visible)').forEach(el=>observer.observe(el));
}
function updateMotion(){
 document.documentElement.classList.toggle('motion-paused',motionPaused);
 document.querySelector('#motion').textContent=t(motionPaused?'resumeMotion':'pauseMotion');
 document.querySelector('#motion').setAttribute('aria-pressed',String(motionPaused));
}
document.querySelector('#language').addEventListener('click',()=>setLanguage(language==='en'?'ar':'en'));
document.querySelector('#motion').addEventListener('click',()=>{motionPaused=!motionPaused;updateMotion();try{localStorage.setItem('portfolio-motion',motionPaused?'paused':'running')}catch{}});
document.querySelector('#projects').addEventListener('click',event=>{const button=event.target.closest('[data-project]');if(!button)return;activeProject=Number(button.dataset.project);renderDialog(activeProject);dialog.showModal()});
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});
dialog.addEventListener('close',()=>{activeProject=null});
let scrollQueued=false;
function updateProgress(){const total=document.documentElement.scrollHeight-window.innerHeight;document.querySelector('.scroll-progress').style.width=`${total>0?window.scrollY/total*100:0}%`;scrollQueued=false}
window.addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(updateProgress)}},{passive:true});
window.addEventListener('resize',updateProgress);
const hero=document.querySelector('.hero');const visual=document.querySelector('.hero-visual');
hero.addEventListener('pointermove',event=>{if(motionPaused||reducedMotion.matches||event.pointerType!=='mouse')return;const r=hero.getBoundingClientRect();visual.style.setProperty('--px',`${(event.clientX-r.left-r.width/2)*.012}px`);visual.style.setProperty('--py',`${(event.clientY-r.top-r.height/2)*.016}px`)});
hero.addEventListener('pointerleave',()=>{visual.style.setProperty('--px','0px');visual.style.setProperty('--py','0px')});
reducedMotion.addEventListener('change',event=>{if(event.matches){motionPaused=true;updateMotion()}});
if('IntersectionObserver' in window)document.documentElement.classList.add('js-motion');
document.querySelector('#year').textContent=new Date().getFullYear();
setLanguage(language);updateProgress();
